"""Rewrite `sa.Enum(...)` columns in an autogenerated migration as `sa.String(32)` + an explicit CHECK (ADR-023).

    uv run python scripts/freeze_enums.py migrations/versions/<new file>.py

Why: a migration is a frozen snapshot. `sa.Enum(Role)`-style columns would change meaning if the Python enum gains a
value later; plain varchar + `CHECK (col IN (...))` says exactly what the database looked like at that revision.
The CHECK keeps the name SQLAlchemy uses for the model (`ck_<table>_<enum name>`), so `alembic check` stays clean.
"""

import re
import sys
from pathlib import Path


def freeze(source: str) -> str:
    new = source
    for block in re.finditer(r'    op\.create_table\(\n        "(\w+)",(.*?)\n    \)\n', source, re.S):
        table, body = block.group(1), block.group(2)
        checks: list[str] = []

        def to_string(match: re.Match[str], table: str = table, checks: list[str] = checks) -> str:
            column, inner = match.group(1), match.group(2)
            values = re.findall(r'"([A-Z_]+)"', inner.split("name=")[0])
            name_match = re.search(r'name="(\w+)"', inner)
            if name_match is None:
                raise SystemExit(f"enum on {table}.{column} has no name=")
            listed = ", ".join(f"'{v}'" for v in values)
            checks.append(
                f'        sa.CheckConstraint("{column} IN ({listed})", name=op.f("ck_{table}_{name_match.group(1)}")),'
            )
            return f'sa.Column(\n            "{column}",\n            sa.String(32),'

        frozen = re.sub(r'sa\.Column\(\n\s+"(\w+)",\n\s+sa\.Enum\((.*?)\),', to_string, body, flags=re.S)
        if checks:
            frozen += "\n" + "\n".join(checks)
        new = new.replace(block.group(0), f'    op.create_table(\n        "{table}",{frozen}\n    )\n')
    for marker in (
        "    # ### commands auto generated by Alembic - please adjust! ###\n",
        "    # ### end Alembic commands ###\n",
    ):
        new = new.replace(marker, "")
    return new


if __name__ == "__main__":
    for path in map(Path, sys.argv[1:]):
        path.write_text(freeze(path.read_text()))
        print(f"froze enums in {path}")
